#!/usr/bin/env bash
# ============================================================================
# ⚡ KentScript v3.1.0 Installer
# Auto-generated by build_binary.py — do not edit manually
# ============================================================================
set -e

BINARY_NAME="kentscript"
SYSTEM_BIN="/usr/local/bin"
USER_BIN="$HOME/.local/bin"
CACHE_DIR="$HOME/.cache/kentscript"
VERSION="3.1.0"
MANIFEST_URL="https://github.com/musikaalvin/kentscript/raw/main/manifest.json"
BINARY_URL="https://github.com/musikaalvin/kentscript/raw/main/kentscript"
SOURCE_BASE="https://github.com/musikaalvin/kentscript/raw/main"
LOCAL_MODE=false

# ── Colours ──────────────────────────────────────────────────────────────────
R='\033[0m';  BOLD='\033[1m';  DIM='\033[2m'
FG_WHITE='\033[97m';  FG_CYAN='\033[96m';  FG_GREEN='\033[92m'
FG_YELLOW='\033[93m'; FG_RED='\033[91m';   FG_BLUE='\033[94m'
FG_GRAY='\033[90m';   BAR_FILL='\033[38;5;51m'; BAR_EMPTY='\033[38;5;238m'
TW=$(tput cols 2>/dev/null || echo 68); [ "$TW" -gt 72 ] && TW=72

_TOTAL=6; _STEP=0
draw_bar() {
    local step=$1 total=$2 label="$3"
    local bw=$(( TW-16 )); [ $bw -lt 20 ] && bw=20
    local f=$(( step*bw/total )) e=$(( bw - step*bw/total )) pct=$(( step*100/total ))
    if [ "$step" -lt "$total" ]; then
        printf "  ${FG_GRAY}[${R}${BAR_FILL}"; for((i=0;i<f;i++)); do printf "█"; done
        printf "${BAR_EMPTY}";                     for((i=0;i<e;i++)); do printf "░"; done
        printf "${R}${FG_GRAY}]${R} ${BOLD}${FG_CYAN}%3d%%${R}  ${FG_GRAY}Step %d/%d  %s${R}\n" "$pct" "$step" "$total" "$label"
    else
        printf "  ${FG_GRAY}[${R}${BAR_FILL}"; for((i=0;i<bw;i++)); do printf "█"; done
        printf "${R}${FG_GRAY}]${R} ${BOLD}${FG_CYAN}100%%${R}  ${FG_GRAY}Step $total/$total  ${FG_GREEN}${BOLD}$label${R}\n"
    fi
}
advance()  { _STEP=$((_STEP+1)); echo ""; draw_bar "$_STEP" "$_TOTAL" "$1"; }
activity() { local m="$1" max=$((TW-6)); [ "${#m}" -gt "$max" ] && m="${m:0:$((max-1))}…"
              printf "  ${FG_GRAY}${DIM}▸  %s${R}\n" "$m"; }
log_ok()   { echo -e "  ${FG_GREEN}✔${R}  ${FG_GREEN}${BOLD}$*${R}"; }
log_info() { echo -e "  ${FG_CYAN}ℹ${R}  ${FG_WHITE}$*${R}"; }
log_warn() { echo -e "  ${FG_YELLOW}⚠${R}  ${FG_YELLOW}$*${R}"; }
log_err()  { echo -e "  ${FG_RED}✘${R}  ${FG_RED}${BOLD}$*${R}"; exit 1; }
log_kv()   { local k="$1" v="$2" vc="${3:-$FG_BLUE}"
              echo -e "  ${FG_GRAY}    $k:${R} ${vc}${BOLD}$v${R}"; }

banner() {
    echo ""
    local sep=""; for((i=0;i<TW;i++)); do sep+="═"; done
    echo -e "${FG_CYAN}${sep}${R}"
    local t="⚡  KentScript v$VERSION Installer"
    printf "%*s${BOLD}${FG_CYAN}%s${R}\n" "$(( (TW-${#t})/2 ))" "" "$t"
    echo -e "${FG_CYAN}${sep}${R}"; echo ""
}

# ── Get installed version ─────────────────────────────────────────────────────
get_version() {
    local bin="${1:-kentscript}"
    local v
    v=$( "$bin" --ks-version 2>/dev/null ) && [ -n "$v" ] && { echo "$v"; return; }
    v=$( "$bin" --version 2>/dev/null | grep -oE '[0-9]+[.][0-9]+([.][0-9]+)?' | head -1 )
    [ -n "$v" ] && { echo "$v"; return; }
    echo "unknown"
}

# ── Fetch manifest ────────────────────────────────────────────────────────────
fetch_manifest() {
    local url="$1" tmp http_code body
    tmp=$(mktemp)
    http_code=$(curl -sSL --max-time 15 -w "%{http_code}" -o "$tmp" "$url" 2>/dev/null || echo "000")
    http_code=$(echo "$http_code" | tail -c 4 | tr -d '\n')
    body=$(cat "$tmp" 2>/dev/null || echo ""); rm -f "$tmp"
    case "$http_code" in
        200) echo "ok:$body" ;;
        404) echo "notfound"  ;;
        *)   echo "offline"   ;;
    esac
}

# ── Parse args ────────────────────────────────────────────────────────────────
USER_INSTALL=false; UNINSTALL=false; UPDATE_MODE=false
UPDATE_CHECK=false; OFFLINE=false

for arg in "$@"; do
    case "$arg" in
        --user)         USER_INSTALL=true ;;
        --uninstall)    UNINSTALL=true ;;
        --update)       UPDATE_MODE=true ;;
        --update-check) UPDATE_CHECK=true ;;
        --offline)      OFFLINE=true ;;
        --help|-h)
            cat << 'HELP'

  Usage: bash install.sh [OPTION]

    (no flags)      System-wide install (requires sudo)
    --user          Install for current user only
    --offline       Install from local kentscript binary
    --update        Update to latest version from GitHub
    --update-check  Check if update is available (no install)
    --uninstall     Remove KentScript
    --help          Show this help

HELP
            exit 0 ;;
    esac
done

# ═════════════════════════════════════════════════════════════════════════════
# UPDATE-CHECK
# ═════════════════════════════════════════════════════════════════════════════
if $UPDATE_CHECK; then
    echo ""
    echo -e "${BOLD}${FG_CYAN}  ⚡  KentScript — Update Check${R}"
    echo -e "${FG_GRAY}  $(printf '─%.0s' $(seq 1 50))${R}"
    echo ""
    if ! command -v kentscript &>/dev/null; then
        log_err "KentScript is not installed. Run: bash install.sh"
    fi
    CURRENT=$(get_version kentscript)
    log_info "Installed: v$CURRENT"
    log_info "Fetching manifest from GitHub..."
    RESULT=$(fetch_manifest "$MANIFEST_URL")
    case "$RESULT" in
        offline)  log_warn "Cannot reach GitHub."; echo ""; exit 1 ;;
        notfound) log_warn "manifest.json not found on GitHub."; echo ""; exit 1 ;;
    esac
    MANIFEST="${RESULT#ok:}"
    NEW=$(echo "$MANIFEST" | grep -o '"version"[[:space:]]*:[[:space:]]*"[^"]*"' | cut -d'"' -f4)
    echo ""
    echo -e "  ${FG_GRAY}┌─────────────────────┬─────────────────────────┐${R}"
    printf  "  ${FG_GRAY}│${R} %-19s ${FG_GRAY}│${R} ${FG_BLUE}${BOLD}%-23s${R} ${FG_GRAY}│${R}\n" "Installed" "v$CURRENT"
    printf  "  ${FG_GRAY}│${R} %-19s ${FG_GRAY}│${R} ${FG_GREEN}${BOLD}%-23s${R} ${FG_GRAY}│${R}\n" "Latest on GitHub" "v$NEW"
    echo -e "  ${FG_GRAY}└─────────────────────┴─────────────────────────┘${R}"
    echo ""
    if [ "$CURRENT" = "$NEW" ]; then
        log_ok "You are on the latest version (v$CURRENT)"
    else
        log_warn "Update available: v$CURRENT  →  v$NEW"
        echo -e "  ${FG_CYAN}Run:  ${BOLD}bash install.sh --update${R}"
    fi
    echo ""; exit 0
fi

# ═════════════════════════════════════════════════════════════════════════════
# UPDATE
# ═════════════════════════════════════════════════════════════════════════════
if $UPDATE_MODE; then
    echo ""
    echo -e "${BOLD}${FG_CYAN}  ⚡  KentScript — Updater${R}"
    echo -e "${FG_GRAY}  $(printf '─%.0s' $(seq 1 50))${R}"
    echo ""
    log_info "Detecting installation..."
    if ! command -v kentscript &>/dev/null; then
        log_err "KentScript not found. Run: bash install.sh"
    fi
    INSTALL_PATH_BIN="$(command -v kentscript)"
    log_ok "Found: $INSTALL_PATH_BIN"
    case "$INSTALL_PATH_BIN" in
        /usr/local/bin/*) SUDO="sudo" ;;
        "$HOME/.local/bin/"*) SUDO="" ;;
        *) SUDO="sudo" ;;
    esac
    log_info "Fetching manifest from GitHub..."
    RESULT=$(fetch_manifest "$MANIFEST_URL")
    case "$RESULT" in
        offline)  log_err "Cannot reach GitHub." ;;
        notfound) log_err "manifest.json not found on GitHub." ;;
    esac
    MANIFEST="${RESULT#ok:}"
    NEW=$(echo "$MANIFEST" | grep -o '"version"[[:space:]]*:[[:space:]]*"[^"]*"' | cut -d'"' -f4)
    CURRENT=$(get_version "$INSTALL_PATH_BIN")
    echo ""
    echo -e "  ${FG_GRAY}┌─────────────────────┬─────────────────────────┐${R}"
    printf  "  ${FG_GRAY}│${R} %-19s ${FG_GRAY}│${R} ${FG_BLUE}${BOLD}%-23s${R} ${FG_GRAY}│${R}\n" "Installed" "v$CURRENT"
    printf  "  ${FG_GRAY}│${R} %-19s ${FG_GRAY}│${R} ${FG_GREEN}${BOLD}%-23s${R} ${FG_GRAY}│${R}\n" "Latest on GitHub" "v$NEW"
    echo -e "  ${FG_GRAY}└─────────────────────┴─────────────────────────┘${R}"
    echo ""
    if [ "$CURRENT" = "$NEW" ]; then
        log_ok "Already up to date — v$CURRENT is the latest."
        echo ""; exit 0
    fi
    log_info "Downloading v$NEW from GitHub..."
    activity "URL: $BINARY_URL"
    TMP=$(mktemp /tmp/kentscript_update_XXXXXX)
    if curl -fL --progress-bar --max-time 60 -o "$TMP" "$BINARY_URL" 2>&1; then
        if [ ! -s "$TMP" ]; then
            rm -f "$TMP"
            log_err "Downloaded file is empty. Check if dist/kentscript exists in repo."
        fi
        $SUDO cp "$TMP" "$INSTALL_PATH_BIN"
        $SUDO chmod +x "$INSTALL_PATH_BIN"
        rm -f "$TMP"
        rm -rf "$CACHE_DIR"
        echo ""
        echo -e "  ${FG_GREEN}$(printf '═%.0s' $(seq 1 50))${R}"
        echo -e "  ${BOLD}${FG_GREEN}  ✔  Updated  v$CURRENT  →  v$NEW${R}"
        echo -e "  ${FG_GREEN}$(printf '═%.0s' $(seq 1 50))${R}"
        echo ""
    else
        rm -f "$TMP"
        log_err "Download failed. Ensure dist/kentscript and dist/manifest.json are pushed to GitHub."
    fi
    exit 0
fi

# ═════════════════════════════════════════════════════════════════════════════
# UNINSTALL
# ═════════════════════════════════════════════════════════════════════════════
if $UNINSTALL; then
    echo ""
    echo -e "${BOLD}${FG_CYAN}  ⚡  KentScript — Uninstaller${R}"
    echo -e "${FG_GRAY}  $(printf '─%.0s' $(seq 1 50))${R}"
    echo ""
    removed=0
    for p in "/usr/local/bin/$BINARY_NAME" "$HOME/.local/bin/$BINARY_NAME"; do
        if [ -f "$p" ]; then
            sudo rm -f "$p" 2>/dev/null || rm -f "$p" 2>/dev/null || true
            log_ok "Removed $p"; removed=$((removed+1))
        fi
    done
    [ $removed -eq 0 ] && log_warn "KentScript not found in standard locations."
    [ -d "$CACHE_DIR" ] && rm -rf "$CACHE_DIR" && log_ok "Cache removed"
    echo ""
    echo -e "${FG_GREEN}$(printf '═%.0s' $(seq 1 50))${R}"
    echo -e "${BOLD}${FG_GREEN}  ✔  KentScript uninstalled${R}"
    echo -e "${FG_GREEN}$(printf '═%.0s' $(seq 1 50))${R}"
    echo ""; exit 0
fi

# ═════════════════════════════════════════════════════════════════════════════
# INSTALL
# ═════════════════════════════════════════════════════════════════════════════
if $USER_INSTALL; then
    BIN_DIR="$USER_BIN"; SUDO=""
else
    BIN_DIR="$SYSTEM_BIN"; SUDO="sudo"
    if [[ $EUID -ne 0 ]] && ! sudo -n true 2>/dev/null; then
        echo -e "${FG_YELLOW}  sudo required — re-running with sudo...${R}"
        exec sudo bash "$0" "$@"
    fi
fi

DEST="$BIN_DIR/$BINARY_NAME"
SCRIPT_DIR_ABS="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
LOCAL_BIN="$SCRIPT_DIR_ABS/kentscript"

banner

# Step 1 — Binary
advance "Checking Binary"
if $OFFLINE; then
    activity "Scanning local directory..."
    [ ! -f "$LOCAL_BIN" ] && log_err "Local binary not found: $LOCAL_BIN"
    SOURCE="$LOCAL_BIN"
    log_ok "Local binary found"
    log_kv "Size" "$(du -h "$LOCAL_BIN" | cut -f1)"
else
    TMP_DL=$(mktemp /tmp/kentscript_install_XXXXXX)
    activity "Connecting to GitHub..."
    RESULT=$(fetch_manifest "$MANIFEST_URL")
    case "$RESULT" in
        offline)
            log_warn "Cannot reach GitHub."
            if [ -f "$LOCAL_BIN" ]; then
                echo -ne "  ${FG_YELLOW}❓  Local binary found — install it? [Y/n] ${R}"
                read -r ans; [[ "$ans" =~ ^[Nn]$ ]] && { rm -f "$TMP_DL"; log_err "Cancelled."; }
                SOURCE="$LOCAL_BIN"
            else
                rm -f "$TMP_DL"
                log_err "No binary available. Place ./kentscript here or use --offline."
            fi ;;
        notfound)
            log_warn "Binary not on GitHub yet."
            if [ -f "$LOCAL_BIN" ]; then
                echo -ne "  ${FG_YELLOW}❓  Local binary found — install it? [Y/n] ${R}"
                read -r ans; [[ "$ans" =~ ^[Nn]$ ]] && { rm -f "$TMP_DL"; log_err "Cancelled."; }
                SOURCE="$LOCAL_BIN"
            else
                rm -f "$TMP_DL"
                log_err "Push to GitHub first: git add dist/ && git push"
            fi ;;
        ok:*)
            activity "Downloading binary..."
            if curl -fL --progress-bar -o "$TMP_DL" "$BINARY_URL" 2>/dev/null; then
                SOURCE="$TMP_DL"
                log_ok "Downloaded ($(du -h "$TMP_DL" | cut -f1))"
            else
                log_warn "Download failed."
                if [ -f "$LOCAL_BIN" ]; then
                    echo -ne "  ${FG_YELLOW}❓  Use local binary instead? [Y/n] ${R}"
                    read -r ans; [[ "$ans" =~ ^[Nn]$ ]] && { rm -f "$TMP_DL"; log_err "Cancelled."; }
                    SOURCE="$LOCAL_BIN"
                else
                    rm -f "$TMP_DL"; log_err "No binary available."
                fi
            fi ;;
    esac
fi

# Step 2 — Dependencies
advance "Checking Dependencies"
activity "Checking python3..."
command -v python3 &>/dev/null || log_err "Python 3.8+ required: sudo apt install python3"
log_ok "Python $(python3 --version 2>&1 | awk '{print $2}')"
activity "Checking gcc..."
GCC=$(gcc --version 2>/dev/null | head -1 | grep -oE '[0-9]+[.][0-9]+[.]?[0-9]*' | head -1 || echo "")
[ -n "$GCC" ] && log_ok "GCC $GCC" || log_warn "GCC not found — Ring 0 features limited"

# Step 3 — Directories
advance "Creating Directories"
$SUDO mkdir -p "$BIN_DIR"
$SUDO mkdir -p "$CACHE_DIR" 2>/dev/null || true
log_ok "Directories ready"
log_kv "Bin"   "$BIN_DIR"
log_kv "Cache" "$CACHE_DIR"

# Step 4 — Install
advance "Installing Binary"
activity "Clearing old caches..."
for v in v2.9 v3.0 v3.0.0 v3.1 v3.2; do [ -d "$CACHE_DIR/$v" ] && rm -rf "$CACHE_DIR/$v"; done
activity "Copying to $DEST..."
$SUDO cp "$SOURCE" "$DEST"
$SUDO chmod +x "$DEST"
[ -n "${TMP_DL:-}" ] && rm -f "$TMP_DL"
[ ! -x "$DEST" ] && log_err "Install failed — binary not executable"
log_ok "Installed: $DEST"

# Step 5 — Man page
advance "Writing Documentation"
MAN_DIR="/usr/local/share/man/man1"
if $SUDO test -d "$MAN_DIR" 2>/dev/null || [ -d "$MAN_DIR" ]; then
    $SUDO tee "$MAN_DIR/kentscript.1" >/dev/null 2>&1 <<'MAN' || true
.TH KENTSCRIPT 1 "2026" "KentScript" "KentScript Manual"
.SH NAME
kentscript \- systems programming language with Ring 0 support
.SH COMMANDS
run, build, jit, ring0, repl, info, audit, security, direct-llvm, typed-c
.SH AUTHOR
pyLord (musikaalvin)
MAN
    log_ok "Man page installed"
else
    log_warn "Man page skipped (no $MAN_DIR)"
fi

# Step 6 — Done
advance "Finalizing"
log_ok "All done"

# PATH warning
if $USER_INSTALL && [[ ":$PATH:" != *":$USER_BIN:"* ]]; then
    echo ""; log_warn "$USER_BIN not in PATH"
    echo -ne "  ${FG_YELLOW}❓  Add to shell config? [Y/n] ${R}"
    read -r ans
    if [[ ! "$ans" =~ ^[Nn]$ ]]; then
        SHELL_RC="$HOME/.bashrc"
        [ -f "$HOME/.zshrc" ] && SHELL_RC="$HOME/.zshrc"
        { echo ''; echo '# KentScript'; echo 'export PATH="$HOME/.local/bin:$PATH"'; } >> "$SHELL_RC"
        log_ok "Added to $SHELL_RC"
    fi
fi

echo ""
echo -e "  ${FG_GRAY}┌───────────────────┬─────────────────────────────────────┐${R}"
printf  "  ${FG_GRAY}│${R} %-17s ${FG_GRAY}│${R} ${FG_BLUE}${BOLD}%-35s${R} ${FG_GRAY}│${R}\n" "Location" "$DEST"
printf  "  ${FG_GRAY}│${R} %-17s ${FG_GRAY}│${R} ${FG_GREEN}${BOLD}%-35s${R} ${FG_GRAY}│${R}\n" "Version"  "v$VERSION"
printf  "  ${FG_GRAY}│${R} %-17s ${FG_GRAY}│${R} ${FG_GREEN}${BOLD}%-35s${R} ${FG_GRAY}│${R}\n" "Status"   "Ready  ✔"
echo -e "  ${FG_GRAY}└───────────────────┴─────────────────────────────────────┘${R}"
echo ""
echo -e "  ${BOLD}${FG_WHITE}Quick Commands${R}"
echo -e "  ${FG_GRAY}·${R}  ${FG_CYAN}${BOLD}kentscript run file.ks${R}        ${FG_GRAY}run a script${R}"
echo -e "  ${FG_GRAY}·${R}  ${FG_CYAN}${BOLD}kentscript repl${R}               ${FG_GRAY}interactive REPL${R}"
echo -e "  ${FG_GRAY}·${R}  ${FG_CYAN}${BOLD}kentscript security${R}           ${FG_GRAY}KSecurity console${R}"
echo -e "  ${FG_GRAY}·${R}  ${FG_CYAN}${BOLD}kentscript --version${R}          ${FG_GRAY}show version${R}"
echo -e "  ${FG_GRAY}·${R}  ${FG_CYAN}${BOLD}bash install.sh --update${R}      ${FG_GRAY}update${R}"
echo -e "  ${FG_GRAY}·${R}  ${FG_CYAN}${BOLD}bash install.sh --uninstall${R}   ${FG_GRAY}remove${R}"
echo ""
echo -e "  ${DIM}${FG_GRAY}📦 https://github.com/musikaalvin/kentscript${R}"
echo ""
